-- Korur Database Schema - Create Control Template Tables
-- V1_1_12__Create_Korur_Template_Tables.sql
--
-- Phase 12: Creates the ISO 27001:2022 Annex A control template catalogue.
-- Provides a read-only reference table (control_templates) seeded with all
-- 93 standard controls so organizations can import them into their own
-- controls table rather than entering them manually.

-- =====================================================
-- 1. Create control_templates table
-- =====================================================

CREATE TABLE korur.control_templates (
    id           UUID         NOT NULL,
    code         VARCHAR(20)  NOT NULL,
    category     korur.control_control_category_enum NOT NULL,
    control_type korur.control_control_type_enum     NOT NULL,
    theme        VARCHAR(100) NOT NULL,
    name         VARCHAR(255) NOT NULL,
    description  TEXT,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT control_templates_pk PRIMARY KEY (id),
    CONSTRAINT control_templates_code_uq UNIQUE (code)
);

-- =====================================================
-- 2. Create indexes
-- =====================================================

CREATE INDEX control_templates_category_idx ON korur.control_templates(category);

