INSERT INTO korur.control_templates (id, code, category, control_type, theme, name, description) VALUES
(gen_random_uuid(), 'A.5.1',  'ORGANIZATIONAL', 'PREVENTIVE', 'Governance',            'Policies for information security',                                          'A set of policies for information security shall be defined, approved by management, published, communicated to and acknowledged by relevant personnel and relevant interested parties, and reviewed at planned intervals or if significant changes occur.'),
(gen_random_uuid(), 'A.5.2',  'ORGANIZATIONAL', 'PREVENTIVE', 'Governance',            'Information security roles and responsibilities',                             'Information security roles and responsibilities shall be defined and allocated to ensure clear accountability for the protection of information and other associated assets.'),
(gen_random_uuid(), 'A.5.3',  'ORGANIZATIONAL', 'PREVENTIVE', 'Governance',            'Segregation of duties',                                                       'Conflicting duties and conflicting areas of responsibility shall be segregated to reduce opportunities for unauthorized or unintentional modification or misuse of the organization''s assets.'),
(gen_random_uuid(), 'A.5.4',  'ORGANIZATIONAL', 'PREVENTIVE', 'Governance',            'Management responsibilities',                                                 'Management shall require all personnel to apply information security in accordance with the established information security policy, topic-specific policies and procedures of the organization.'),
(gen_random_uuid(), 'A.5.5',  'ORGANIZATIONAL', 'PREVENTIVE', 'Governance',            'Contact with authorities',                                                    'The organization shall establish and maintain contact with relevant authorities to ensure timely information flow regarding legal, regulatory and supervisory obligations related to information security.'),
(gen_random_uuid(), 'A.5.6',  'ORGANIZATIONAL', 'PREVENTIVE', 'Governance',            'Contact with special interest groups',                                        'The organization shall establish and maintain contact with special interest groups or other specialist security forums and professional associations to stay informed about security threats, vulnerabilities and best practices.'),
(gen_random_uuid(), 'A.5.7',  'ORGANIZATIONAL', 'DETECTIVE',  'Governance',            'Threat intelligence',                                                         'Information relating to information security threats shall be collected and analysed to produce threat intelligence that informs risk mitigation decisions and strengthens defensive controls.'),
(gen_random_uuid(), 'A.5.8',  'ORGANIZATIONAL', 'PREVENTIVE', 'Governance',            'Information security in project management',                                  'Information security shall be integrated into project management regardless of the type of project to ensure that information security risks are identified and addressed as part of project delivery.'),
(gen_random_uuid(), 'A.5.9',  'ORGANIZATIONAL', 'PREVENTIVE', 'Asset management',      'Inventory of information and other associated assets',                        'An inventory of information and other associated assets, including owners, shall be developed and maintained to provide a basis for asset protection throughout their lifecycle.'),
(gen_random_uuid(), 'A.5.10', 'ORGANIZATIONAL', 'PREVENTIVE', 'Asset management',      'Acceptable use of information and other associated assets',                   'Rules for the acceptable use of information and other associated assets shall be identified, documented and implemented to ensure assets are used and handled properly.'),
(gen_random_uuid(), 'A.5.11', 'ORGANIZATIONAL', 'PREVENTIVE', 'Asset management',      'Return of assets',                                                            'Personnel and other interested parties as appropriate shall return all the organization''s assets in their possession upon change or termination of their employment, contract or agreement.'),
(gen_random_uuid(), 'A.5.12', 'ORGANIZATIONAL', 'PREVENTIVE', 'Information protection', 'Classification of information',                                               'Information shall be classified according to the information security needs of the organization based on confidentiality, integrity, availability and relevant interested party requirements.'),
(gen_random_uuid(), 'A.5.13', 'ORGANIZATIONAL', 'PREVENTIVE', 'Information protection', 'Labelling of information',                                                    'An appropriate set of procedures for information labelling shall be developed and implemented in accordance with the information classification scheme adopted by the organization.'),
(gen_random_uuid(), 'A.5.14', 'ORGANIZATIONAL', 'PREVENTIVE', 'Information protection', 'Information transfer',                                                        'Information transfer rules, procedures, or agreements shall be in place for all types of transfer facilities within the organization and between the organization and other parties.'),
(gen_random_uuid(), 'A.5.15', 'ORGANIZATIONAL', 'PREVENTIVE', 'Identity & access',     'Access control',                                                              'Rules to control physical and logical access to information and other associated assets shall be established and implemented based on business and information security requirements.'),
(gen_random_uuid(), 'A.5.16', 'ORGANIZATIONAL', 'PREVENTIVE', 'Identity & access',     'Identity management',                                                         'The full life cycle of identities shall be managed, including creation, verification, assignment, suspension and revocation, to ensure only authorized individuals can access organizational resources.'),
(gen_random_uuid(), 'A.5.17', 'ORGANIZATIONAL', 'PREVENTIVE', 'Identity & access',     'Authentication information',                                                  'Allocation and management of authentication information shall be controlled by a management process, including advising personnel on appropriate handling of authentication information.'),
(gen_random_uuid(), 'A.5.18', 'ORGANIZATIONAL', 'PREVENTIVE', 'Identity & access',     'Access rights',                                                               'Access rights to information and other associated assets shall be provisioned, reviewed, modified and removed in accordance with the organization''s topic-specific policy on and rules for access control.'),
(gen_random_uuid(), 'A.5.19', 'ORGANIZATIONAL', 'PREVENTIVE', 'Supplier management',   'Information security in supplier relationships',                              'Processes and procedures shall be defined and implemented to manage the information security risks associated with the use of supplier''s products or services.'),
(gen_random_uuid(), 'A.5.20', 'ORGANIZATIONAL', 'PREVENTIVE', 'Supplier management',   'Addressing information security within supplier agreements',                  'Relevant information security requirements shall be established and agreed with each supplier based on the type of supplier relationship.'),
(gen_random_uuid(), 'A.5.21', 'ORGANIZATIONAL', 'PREVENTIVE', 'Supplier management',   'Managing information security in the ICT supply chain',                       'Processes and procedures shall be defined and implemented to manage the information security risks associated with the ICT products and services supply chain.'),
(gen_random_uuid(), 'A.5.22', 'ORGANIZATIONAL', 'DETECTIVE',  'Supplier management',   'Monitoring, review and change management of supplier services',               'The organization shall regularly monitor, review, evaluate and manage change in supplier information security practices and service delivery to maintain an agreed level of information security.'),
(gen_random_uuid(), 'A.5.23', 'ORGANIZATIONAL', 'PREVENTIVE', 'Cloud security',        'Information security for use of cloud services',                              'Processes for acquisition, use, management and exit from cloud services shall be established in accordance with the organization''s information security requirements.'),
(gen_random_uuid(), 'A.5.24', 'ORGANIZATIONAL', 'PREVENTIVE', 'Incident management',   'Information security incident management planning and preparation',           'The organization shall plan and prepare for managing information security incidents by defining, establishing and communicating information security incident management processes, roles and responsibilities.'),
(gen_random_uuid(), 'A.5.25', 'ORGANIZATIONAL', 'DETECTIVE',  'Incident management',   'Assessment and decision on information security events',                      'The organization shall assess information security events and decide if they are to be categorized as information security incidents.'),
(gen_random_uuid(), 'A.5.26', 'ORGANIZATIONAL', 'CORRECTIVE', 'Incident management',   'Response to information security incidents',                                  'Information security incidents shall be responded to in accordance with the documented procedures to contain impact, preserve evidence and restore normal operations.'),
(gen_random_uuid(), 'A.5.27', 'ORGANIZATIONAL', 'CORRECTIVE', 'Incident management',   'Learning from information security incidents',                                'Knowledge gained from information security incidents shall be used to strengthen and improve the information security controls and incident management processes.'),
(gen_random_uuid(), 'A.5.28', 'ORGANIZATIONAL', 'DETECTIVE',  'Incident management',   'Collection of evidence',                                                      'The organization shall establish and implement procedures for the identification, collection, acquisition and preservation of evidence related to information security events.'),
(gen_random_uuid(), 'A.5.29', 'ORGANIZATIONAL', 'PREVENTIVE', 'Business continuity',   'Information security during disruption',                                      'The organization shall plan how to maintain information security at an appropriate level during disruption to ensure that protective controls continue operating under adverse conditions.'),
(gen_random_uuid(), 'A.5.30', 'ORGANIZATIONAL', 'PREVENTIVE', 'Business continuity',   'ICT readiness for business continuity',                                       'ICT readiness shall be planned, implemented, maintained and tested based on business continuity objectives and ICT continuity requirements.'),
(gen_random_uuid(), 'A.5.31', 'ORGANIZATIONAL', 'PREVENTIVE', 'Compliance',            'Legal, statutory, regulatory and contractual requirements',                   'Legal, statutory, regulatory and contractual requirements relevant to information security and the organization''s approach to meet these requirements shall be identified, documented and kept up to date.'),
(gen_random_uuid(), 'A.5.32', 'ORGANIZATIONAL', 'PREVENTIVE', 'Compliance',            'Intellectual property rights',                                                'The organization shall implement appropriate procedures to protect intellectual property rights, including those related to software and design documents.'),
(gen_random_uuid(), 'A.5.33', 'ORGANIZATIONAL', 'PREVENTIVE', 'Compliance',            'Protection of records',                                                       'Records shall be protected from loss, destruction, falsification, unauthorized access and unauthorized release in accordance with legal, statutory, regulatory and contractual requirements.'),
(gen_random_uuid(), 'A.5.34', 'ORGANIZATIONAL', 'PREVENTIVE', 'Compliance',            'Privacy and protection of PII',                                               'The organization shall identify and meet the requirements regarding the preservation of privacy and protection of personally identifiable information as applicable according to relevant laws, regulations and contractual requirements.'),
(gen_random_uuid(), 'A.5.35', 'ORGANIZATIONAL', 'DETECTIVE',  'Compliance',            'Independent review of information security',                                  'The organization''s approach to managing information security and its implementation including people, processes and technologies shall be reviewed independently at planned intervals, or when significant changes occur.'),
(gen_random_uuid(), 'A.5.36', 'ORGANIZATIONAL', 'DETECTIVE',  'Compliance',            'Compliance with policies, rules and standards for information security',       'Compliance with the organization''s information security policy, topic-specific policies, rules and standards shall be regularly reviewed.'),
(gen_random_uuid(), 'A.5.37', 'ORGANIZATIONAL', 'PREVENTIVE', 'Compliance',            'Documented operating procedures',                                             'Operating procedures for information processing facilities shall be documented and made available to personnel who need them to ensure consistent and secure operations.');
INSERT INTO korur.control_templates (id, code, category, control_type, theme, name, description) VALUES
(gen_random_uuid(), 'A.6.1', 'PEOPLE', 'PREVENTIVE', 'HR security',         'Screening',                                                       'Background verification checks on all candidates to become personnel shall be carried out prior to joining the organization and on an ongoing basis, taking into consideration applicable laws, regulations and ethics, and be proportional to the business requirements, the classification of the information to be accessed and the perceived risks.'),
(gen_random_uuid(), 'A.6.2', 'PEOPLE', 'PREVENTIVE', 'HR security',         'Terms and conditions of employment',                              'The employment contractual agreements shall state the personnel''s and the organization''s responsibilities for information security.'),
(gen_random_uuid(), 'A.6.3', 'PEOPLE', 'PREVENTIVE', 'Security awareness',  'Information security awareness, education and training',           'Organization personnel and relevant interested parties shall receive appropriate information security awareness, education and training and regular updates of the organization''s information security policy, topic-specific policies and procedures, as relevant for their job function.'),
(gen_random_uuid(), 'A.6.4', 'PEOPLE', 'CORRECTIVE', 'HR security',         'Disciplinary process',                                            'A disciplinary process shall be formalized and communicated to take actions against personnel and other relevant interested parties who have committed an information security policy violation.'),
(gen_random_uuid(), 'A.6.5', 'PEOPLE', 'PREVENTIVE', 'HR security',         'Responsibilities after termination or change of employment',       'Information security responsibilities and duties that remain valid after termination or change of employment shall be defined, enforced and communicated to relevant personnel and other interested parties.'),
(gen_random_uuid(), 'A.6.6', 'PEOPLE', 'PREVENTIVE', 'HR security',         'Confidentiality or non-disclosure agreements',                    'Confidentiality or non-disclosure agreements reflecting the organization''s needs for the protection of information shall be identified, documented, regularly reviewed and signed by personnel and other relevant interested parties.'),
(gen_random_uuid(), 'A.6.7', 'PEOPLE', 'PREVENTIVE', 'HR security',         'Remote working',                                                  'Security measures shall be implemented when personnel are working remotely to protect information accessed, processed or stored outside the organization''s premises.'),
(gen_random_uuid(), 'A.6.8', 'PEOPLE', 'DETECTIVE',  'Incident management', 'Information security event reporting',                             'The organization shall provide a mechanism for personnel to report observed or suspected information security events through appropriate channels in a timely manner.');
INSERT INTO korur.control_templates (id, code, category, control_type, theme, name, description) VALUES
(gen_random_uuid(), 'A.7.1',  'PHYSICAL', 'PREVENTIVE', 'Physical security',   'Physical security perimeters',                          'Security perimeters shall be defined and used to protect areas that contain information and other associated assets.'),
(gen_random_uuid(), 'A.7.2',  'PHYSICAL', 'PREVENTIVE', 'Physical security',   'Physical entry',                                        'Secure areas shall be protected by appropriate entry controls and access points to ensure that only authorized personnel are permitted access.'),
(gen_random_uuid(), 'A.7.3',  'PHYSICAL', 'PREVENTIVE', 'Physical security',   'Securing offices, rooms and facilities',                'Physical security for offices, rooms and facilities shall be designed and implemented to protect information and associated assets from unauthorized access, damage and interference.'),
(gen_random_uuid(), 'A.7.4',  'PHYSICAL', 'DETECTIVE',  'Physical security',   'Physical security monitoring',                          'Premises shall be continuously monitored for unauthorized physical access using surveillance systems and detection mechanisms.'),
(gen_random_uuid(), 'A.7.5',  'PHYSICAL', 'PREVENTIVE', 'Physical security',   'Protecting against physical and environmental threats',  'Protection against physical and environmental threats, such as natural disasters and other intentional or unintentional physical threats to infrastructure, shall be designed and implemented.'),
(gen_random_uuid(), 'A.7.6',  'PHYSICAL', 'PREVENTIVE', 'Physical security',   'Working in secure areas',                               'Security measures for working in secure areas shall be designed and implemented to protect information and associated assets within those areas.'),
(gen_random_uuid(), 'A.7.7',  'PHYSICAL', 'PREVENTIVE', 'Physical security',   'Clear desk and clear screen',                           'Clear desk rules for papers and removable storage media and clear screen rules for information processing facilities shall be defined and appropriately enforced.'),
(gen_random_uuid(), 'A.7.8',  'PHYSICAL', 'PREVENTIVE', 'Equipment security',  'Equipment siting and protection',                       'Equipment shall be sited securely and protected to reduce risks from environmental threats, hazards and opportunities for unauthorized access.'),
(gen_random_uuid(), 'A.7.9',  'PHYSICAL', 'PREVENTIVE', 'Equipment security',  'Security of assets off-premises',                       'Off-site assets shall be protected with security measures that account for the different risks of working outside the organization''s premises.'),
(gen_random_uuid(), 'A.7.10', 'PHYSICAL', 'PREVENTIVE', 'Equipment security',  'Storage media',                                         'Storage media shall be managed through their life cycle of acquisition, use, transportation and disposal in accordance with the organization''s classification scheme and handling requirements.'),
(gen_random_uuid(), 'A.7.11', 'PHYSICAL', 'PREVENTIVE', 'Equipment security',  'Supporting utilities',                                  'Information processing facilities shall be protected from power failures and other disruptions caused by failures in supporting utilities.'),
(gen_random_uuid(), 'A.7.12', 'PHYSICAL', 'PREVENTIVE', 'Equipment security',  'Cabling security',                                      'Cables carrying power, data or supporting information services shall be protected from interception, interference or damage.'),
(gen_random_uuid(), 'A.7.13', 'PHYSICAL', 'PREVENTIVE', 'Equipment security',  'Equipment maintenance',                                 'Equipment shall be maintained correctly to ensure availability, integrity and confidentiality of information.'),
(gen_random_uuid(), 'A.7.14', 'PHYSICAL', 'PREVENTIVE', 'Equipment security',  'Secure disposal or re-use of equipment',                'Items of equipment containing storage media shall be verified to ensure that any sensitive data and licensed software has been removed or securely overwritten prior to disposal or re-use.');
INSERT INTO korur.control_templates (id, code, category, control_type, theme, name, description) VALUES
(gen_random_uuid(), 'A.8.1',  'TECHNOLOGICAL', 'PREVENTIVE', 'Endpoint security',         'User endpoint devices',                                        'Information stored on, processed by or accessible via user endpoint devices shall be protected through appropriate technical and organizational measures.'),
(gen_random_uuid(), 'A.8.2',  'TECHNOLOGICAL', 'PREVENTIVE', 'Access control',            'Privileged access rights',                                     'The allocation and use of privileged access rights shall be restricted and managed to prevent unauthorized elevation of privilege and misuse of system controls.'),
(gen_random_uuid(), 'A.8.3',  'TECHNOLOGICAL', 'PREVENTIVE', 'Access control',            'Information access restriction',                               'Access to information and other associated assets shall be restricted in accordance with the established topic-specific policy on access control.'),
(gen_random_uuid(), 'A.8.4',  'TECHNOLOGICAL', 'PREVENTIVE', 'Access control',            'Access to source code',                                        'Read and write access to source code, development tools and software libraries shall be appropriately managed to prevent the introduction of unauthorized functionality and to maintain intellectual property protection.'),
(gen_random_uuid(), 'A.8.5',  'TECHNOLOGICAL', 'PREVENTIVE', 'Authentication',            'Secure authentication',                                        'Secure authentication technologies and procedures shall be established and implemented based on information access restrictions and the topic-specific policy on access control.'),
(gen_random_uuid(), 'A.8.6',  'TECHNOLOGICAL', 'DETECTIVE',  'Operations',                'Capacity management',                                          'The use of resources shall be monitored and adjusted in line with current and expected capacity requirements to ensure the required system performance and availability.'),
(gen_random_uuid(), 'A.8.7',  'TECHNOLOGICAL', 'PREVENTIVE', 'Malware protection',        'Protection against malware',                                   'Protection against malware shall be implemented and supported by appropriate user awareness to prevent, detect and recover from malware infections.'),
(gen_random_uuid(), 'A.8.8',  'TECHNOLOGICAL', 'PREVENTIVE', 'Vulnerability management',  'Management of technical vulnerabilities',                      'Information about technical vulnerabilities of information systems in use shall be obtained, the organization''s exposure to such vulnerabilities shall be evaluated and appropriate measures shall be taken in a timely manner.'),
(gen_random_uuid(), 'A.8.9',  'TECHNOLOGICAL', 'PREVENTIVE', 'Configuration',             'Configuration management',                                     'Configurations, including security configurations, of hardware, software, services and networks shall be established, documented, implemented, monitored and reviewed.'),
(gen_random_uuid(), 'A.8.10', 'TECHNOLOGICAL', 'PREVENTIVE', 'Data lifecycle',            'Information deletion',                                         'Information stored in information systems, devices or in any other storage media shall be deleted when no longer required to prevent unnecessary exposure of sensitive information.'),
(gen_random_uuid(), 'A.8.11', 'TECHNOLOGICAL', 'PREVENTIVE', 'Data lifecycle',            'Data masking',                                                 'Data masking shall be used in accordance with the organization''s topic-specific policy on access control and other related topic-specific policies, and business requirements, taking applicable legislation into consideration.'),
(gen_random_uuid(), 'A.8.12', 'TECHNOLOGICAL', 'DETECTIVE',  'Data lifecycle',            'Data leakage prevention',                                      'Data leakage prevention measures shall be applied to systems, networks and any other devices that process, store or transmit sensitive information to detect and prevent the unauthorized disclosure of information.'),
(gen_random_uuid(), 'A.8.13', 'TECHNOLOGICAL', 'PREVENTIVE', 'Backup & recovery',         'Information backup',                                           'Backup copies of information, software and systems shall be maintained and regularly tested in accordance with the agreed topic-specific policy on backup.'),
(gen_random_uuid(), 'A.8.14', 'TECHNOLOGICAL', 'PREVENTIVE', 'Backup & recovery',         'Redundancy of information processing facilities',              'Information processing facilities shall be implemented with redundancy sufficient to meet availability requirements.'),
(gen_random_uuid(), 'A.8.15', 'TECHNOLOGICAL', 'DETECTIVE',  'Monitoring',                'Logging',                                                      'Logs that record activities, exceptions, faults and other relevant events shall be produced, stored, protected and analysed to detect anomalous behaviour and potential security incidents.'),
(gen_random_uuid(), 'A.8.16', 'TECHNOLOGICAL', 'DETECTIVE',  'Monitoring',                'Monitoring activities',                                        'Networks, systems and applications shall be monitored for anomalous behaviour and appropriate actions taken to evaluate potential information security incidents.'),
(gen_random_uuid(), 'A.8.17', 'TECHNOLOGICAL', 'PREVENTIVE', 'Monitoring',                'Clock synchronization',                                        'The clocks of information processing systems used by the organization shall be synchronized to approved time sources to ensure accurate timestamps for logging and forensic analysis.'),
(gen_random_uuid(), 'A.8.18', 'TECHNOLOGICAL', 'PREVENTIVE', 'System security',           'Use of privileged utility programs',                           'The use of utility programs that can be capable of overriding system and application controls shall be restricted and tightly controlled.'),
(gen_random_uuid(), 'A.8.19', 'TECHNOLOGICAL', 'PREVENTIVE', 'System security',           'Installation of software on operational systems',              'Procedures and measures shall be implemented to securely manage software installation on operational systems and prevent unauthorized or untested software from being deployed.'),
(gen_random_uuid(), 'A.8.20', 'TECHNOLOGICAL', 'PREVENTIVE', 'Network security',          'Networks security',                                            'Networks and network devices shall be secured, managed and controlled to protect information in systems and applications.'),
(gen_random_uuid(), 'A.8.21', 'TECHNOLOGICAL', 'PREVENTIVE', 'Network security',          'Security of network services',                                 'Security mechanisms, service levels and service requirements of network services shall be identified, implemented and monitored, whether provided internally or outsourced.'),
(gen_random_uuid(), 'A.8.22', 'TECHNOLOGICAL', 'PREVENTIVE', 'Network security',          'Segregation of networks',                                      'Groups of information services, users and information systems shall be segregated in the organization''s networks to limit lateral movement and contain security breaches.'),
(gen_random_uuid(), 'A.8.23', 'TECHNOLOGICAL', 'PREVENTIVE', 'Network security',          'Web filtering',                                                'Access to external websites shall be managed to reduce exposure to malicious content.'),
(gen_random_uuid(), 'A.8.24', 'TECHNOLOGICAL', 'PREVENTIVE', 'Cryptography',              'Use of cryptography',                                          'Rules for the effective use of cryptography, including cryptographic key management, shall be defined and implemented to protect the confidentiality, authenticity and integrity of information.'),
(gen_random_uuid(), 'A.8.25', 'TECHNOLOGICAL', 'PREVENTIVE', 'Secure development',        'Secure development life cycle',                                'Rules for the secure development of software and systems shall be established and applied to all development activities within the organization.'),
(gen_random_uuid(), 'A.8.26', 'TECHNOLOGICAL', 'PREVENTIVE', 'Secure development',        'Application security requirements',                            'Information security requirements shall be identified, specified and approved when developing or acquiring applications.'),
(gen_random_uuid(), 'A.8.27', 'TECHNOLOGICAL', 'PREVENTIVE', 'Secure development',        'Secure system architecture and engineering principles',         'Principles for engineering secure systems shall be established, documented, maintained and applied to any information system development activities.'),
(gen_random_uuid(), 'A.8.28', 'TECHNOLOGICAL', 'PREVENTIVE', 'Secure development',        'Secure coding',                                                'Secure coding principles shall be applied to software development to reduce vulnerabilities and prevent common coding weaknesses that could be exploited.'),
(gen_random_uuid(), 'A.8.29', 'TECHNOLOGICAL', 'DETECTIVE',  'Secure development',        'Security testing in development and acceptance',               'Security testing processes shall be defined and implemented in the development life cycle to identify and remediate vulnerabilities before deployment.'),
(gen_random_uuid(), 'A.8.30', 'TECHNOLOGICAL', 'PREVENTIVE', 'Secure development',        'Outsourced development',                                       'The organization shall direct, monitor and review the activities related to outsourced system development to ensure information security requirements are met.'),
(gen_random_uuid(), 'A.8.31', 'TECHNOLOGICAL', 'PREVENTIVE', 'Secure development',        'Separation of development, test and production environments',  'Development, testing and production environments shall be separated and secured to reduce the risk of unauthorized access or changes to the production environment.'),
(gen_random_uuid(), 'A.8.32', 'TECHNOLOGICAL', 'PREVENTIVE', 'Change management',         'Change management',                                            'Changes to information processing facilities and information systems shall be subject to change management procedures to preserve information security throughout the change process.'),
(gen_random_uuid(), 'A.8.33', 'TECHNOLOGICAL', 'PREVENTIVE', 'Data lifecycle',            'Test information',                                             'Test information shall be appropriately selected, protected and managed to prevent exposure of sensitive operational data in test environments.'),
(gen_random_uuid(), 'A.8.34', 'TECHNOLOGICAL', 'DETECTIVE',  'Audit',                     'Protection of information systems during audit testing',        'Audit tests and other assurance activities involving assessment of operational systems shall be planned and agreed between the tester and appropriate management to minimize disruption to business operations.');
